-- ============================================================================
-- T-WINKLE DATABASE | C15 CODEX-READY BACKEND SEED
-- SQL Server / Database: T_Winkle
--
-- PURPOSE
--   Canonical reset + seed database for Codex backend integration/testing.
--   Schema is intentionally kept compatible with the T-Winkle Backend C15
--   canonical contract. Do NOT add/change schema from application code merely
--   to make Java compile.
--
-- IMAGE HANDOFF (TEMPORARY DEV/TEST ASSET)
--   Source asset on the developer machine:
--     D:\Cyan\Project\T-Winkle\Elements\Raw\T-Winkle.png
--
--   Codex MUST copy that file INTO the project before runtime verification:
--     src/main/resources/static/images/storefront/products/T-Winkle.png
--     src/main/resources/static/images/storefront/stores/T-Winkle.png
--     src/main/resources/static/images/storefront/brands/T-Winkle.png
--     src/main/resources/static/images/storefront/categories/T-Winkle.png
--     src/main/resources/static/images/storefront/avatars/T-Winkle.png
--
--   All image-bearing DB records below intentionally point to these project-
--   internal static paths. The absolute D:\... source path is NOT stored in DB.
--
--   IMPORTANT:
--   USERS has NO avatar_url/avatar column in the canonical schema.
--   Do NOT add one. User avatar UI should use the project static fallback:
--     /images/storefront/avatars/T-Winkle.png
--
--   The same temporary asset is intentionally reused for product images,
--   product variant images, store images, brand/category images and user avatar
--   fallback until real assets are supplied.
--
-- RESET SCRIPT
--   This is a DEV/TEST reset script. It drops and recreates the 26 canonical
--   Storefront tables in dependency-safe order, then seeds sample data.
-- ============================================================================

IF DB_ID(N'T_Winkle') IS NULL
BEGIN
    CREATE DATABASE T_Winkle;
END
GO
USE T_Winkle;
GO

IF OBJECT_ID(N'dbo.REVIEWS', N'U') IS NOT NULL DROP TABLE dbo.REVIEWS;
IF OBJECT_ID(N'dbo.ORDER_CANCELLATIONS', N'U') IS NOT NULL DROP TABLE dbo.ORDER_CANCELLATIONS;
IF OBJECT_ID(N'dbo.ORDER_STATUS_HISTORY', N'U') IS NOT NULL DROP TABLE dbo.ORDER_STATUS_HISTORY;
IF OBJECT_ID(N'dbo.PAYMENTS', N'U') IS NOT NULL DROP TABLE dbo.PAYMENTS;
IF OBJECT_ID(N'dbo.ORDER_ITEMS', N'U') IS NOT NULL DROP TABLE dbo.ORDER_ITEMS;
IF OBJECT_ID(N'dbo.COUPON_USAGES', N'U') IS NOT NULL DROP TABLE dbo.COUPON_USAGES;
IF OBJECT_ID(N'dbo.ORDERS', N'U') IS NOT NULL DROP TABLE dbo.ORDERS;
IF OBJECT_ID(N'dbo.CART_ITEMS', N'U') IS NOT NULL DROP TABLE dbo.CART_ITEMS;
IF OBJECT_ID(N'dbo.CARTS', N'U') IS NOT NULL DROP TABLE dbo.CARTS;
IF OBJECT_ID(N'dbo.WISHLIST_ITEMS', N'U') IS NOT NULL DROP TABLE dbo.WISHLIST_ITEMS;
IF OBJECT_ID(N'dbo.USER_ADDRESSES', N'U') IS NOT NULL DROP TABLE dbo.USER_ADDRESSES;
IF OBJECT_ID(N'dbo.PRODUCT_PROMOTIONS', N'U') IS NOT NULL DROP TABLE dbo.PRODUCT_PROMOTIONS;
IF OBJECT_ID(N'dbo.PROMOTIONS', N'U') IS NOT NULL DROP TABLE dbo.PROMOTIONS;
IF OBJECT_ID(N'dbo.STORE_INVENTORY', N'U') IS NOT NULL DROP TABLE dbo.STORE_INVENTORY;
IF OBJECT_ID(N'dbo.PRODUCT_VARIANTS', N'U') IS NOT NULL DROP TABLE dbo.PRODUCT_VARIANTS;
IF OBJECT_ID(N'dbo.PRODUCT_IMAGES', N'U') IS NOT NULL DROP TABLE dbo.PRODUCT_IMAGES;
IF OBJECT_ID(N'dbo.PRODUCTS', N'U') IS NOT NULL DROP TABLE dbo.PRODUCTS;
IF OBJECT_ID(N'dbo.BRANDS', N'U') IS NOT NULL DROP TABLE dbo.BRANDS;
IF OBJECT_ID(N'dbo.CATEGORIES', N'U') IS NOT NULL DROP TABLE dbo.CATEGORIES;
IF OBJECT_ID(N'dbo.STORES', N'U') IS NOT NULL DROP TABLE dbo.STORES;
IF OBJECT_ID(N'dbo.PASSWORD_RESET_TOKENS', N'U') IS NOT NULL DROP TABLE dbo.PASSWORD_RESET_TOKENS;
IF OBJECT_ID(N'dbo.OTP_VERIFICATIONS', N'U') IS NOT NULL DROP TABLE dbo.OTP_VERIFICATIONS;
IF OBJECT_ID(N'dbo.USER_ROLES', N'U') IS NOT NULL DROP TABLE dbo.USER_ROLES;
IF OBJECT_ID(N'dbo.USERS', N'U') IS NOT NULL DROP TABLE dbo.USERS;
IF OBJECT_ID(N'dbo.ROLES', N'U') IS NOT NULL DROP TABLE dbo.ROLES;
GO

CREATE TABLE dbo.ROLES (
    id INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_ROLES PRIMARY KEY,
    name VARCHAR(50) NOT NULL CONSTRAINT UQ_ROLES_NAME UNIQUE
);
GO

CREATE TABLE dbo.USERS (
    email VARCHAR(100) NOT NULL CONSTRAINT PK_USERS PRIMARY KEY,
    username VARCHAR(50) NOT NULL,
    full_name NVARCHAR(100) NULL,
    phone VARCHAR(20) NULL,
    password_hash VARCHAR(255) NOT NULL,
    is_enabled BIT NOT NULL CONSTRAINT DF_USERS_IS_ENABLED DEFAULT 1,
    created_at DATETIME2(0) NOT NULL CONSTRAINT DF_USERS_CREATED_AT DEFAULT SYSDATETIME(),
    updated_at DATETIME2(0) NOT NULL CONSTRAINT DF_USERS_UPDATED_AT DEFAULT SYSDATETIME()
);
GO

CREATE TABLE dbo.USER_ROLES (
    user_email VARCHAR(100) NOT NULL,
    role_id INT NOT NULL,
    CONSTRAINT PK_USER_ROLES PRIMARY KEY (user_email, role_id),
    CONSTRAINT FK_USER_ROLES_USER FOREIGN KEY (user_email) REFERENCES dbo.USERS(email),
    CONSTRAINT FK_USER_ROLES_ROLE FOREIGN KEY (role_id) REFERENCES dbo.ROLES(id)
);
GO

CREATE TABLE dbo.OTP_VERIFICATIONS (
    id BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_OTP_VERIFICATIONS PRIMARY KEY,
    user_email VARCHAR(100) NULL,
    hashed_otp VARCHAR(255) NOT NULL,
    expires_at DATETIME2(0) NOT NULL,
    attempts INT NOT NULL CONSTRAINT DF_OTP_ATTEMPTS DEFAULT 0,
    type VARCHAR(20) NOT NULL,
    is_used BIT NOT NULL CONSTRAINT DF_OTP_IS_USED DEFAULT 0,
    created_at DATETIME2(0) NOT NULL CONSTRAINT DF_OTP_CREATED_AT DEFAULT SYSDATETIME(),
    CONSTRAINT FK_OTP_USER FOREIGN KEY (user_email) REFERENCES dbo.USERS(email)
);
GO

CREATE TABLE dbo.PASSWORD_RESET_TOKENS (
    id BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_PASSWORD_RESET_TOKENS PRIMARY KEY,
    user_email VARCHAR(100) NULL,
    hashed_token VARCHAR(255) NOT NULL,
    expires_at DATETIME2(0) NOT NULL,
    is_used BIT NOT NULL CONSTRAINT DF_RESET_IS_USED DEFAULT 0,
    created_at DATETIME2(0) NOT NULL CONSTRAINT DF_RESET_CREATED_AT DEFAULT SYSDATETIME(),
    CONSTRAINT FK_RESET_USER FOREIGN KEY (user_email) REFERENCES dbo.USERS(email)
);
GO

CREATE TABLE dbo.STORES (
    store_id INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_STORES PRIMARY KEY,
    slug VARCHAR(80) NOT NULL CONSTRAINT UQ_STORES_SLUG UNIQUE,
    name NVARCHAR(150) NOT NULL,
    description NVARCHAR(500) NULL,
    image_url NVARCHAR(500) NULL,
    phone VARCHAR(20) NULL,
    address_line NVARCHAR(200) NOT NULL,
    ward NVARCHAR(100) NULL,
    district NVARCHAR(100) NULL,
    city NVARCHAR(100) NOT NULL,
    status VARCHAR(20) NOT NULL,
    rating_average DECIMAL(3,2) NOT NULL CONSTRAINT DF_STORES_RATING DEFAULT 0,
    review_count INT NOT NULL CONSTRAINT DF_STORES_REVIEW_COUNT DEFAULT 0,
    manager_email VARCHAR(100) NULL,
    created_at DATETIME2(0) NOT NULL CONSTRAINT DF_STORES_CREATED_AT DEFAULT SYSDATETIME(),
    CONSTRAINT FK_STORES_MANAGER FOREIGN KEY (manager_email) REFERENCES dbo.USERS(email),
    CONSTRAINT CK_STORES_STATUS CHECK (status IN ('OPEN','CLOSED')),
    CONSTRAINT CK_STORES_RATING CHECK (rating_average >= 0 AND rating_average <= 5),
    CONSTRAINT CK_STORES_REVIEW_COUNT CHECK (review_count >= 0)
);
GO

CREATE TABLE dbo.CATEGORIES (
    id INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_CATEGORIES PRIMARY KEY,
    slug VARCHAR(80) NOT NULL CONSTRAINT UQ_CATEGORIES_SLUG UNIQUE,
    name NVARCHAR(100) NOT NULL CONSTRAINT UQ_CATEGORIES_NAME UNIQUE,
    description NVARCHAR(500) NULL,
    image_url NVARCHAR(500) NULL,
    status VARCHAR(20) NOT NULL CONSTRAINT DF_CATEGORIES_STATUS DEFAULT 'ACTIVE',
    created_at DATETIME2(0) NOT NULL CONSTRAINT DF_CATEGORIES_CREATED_AT DEFAULT SYSDATETIME(),
    updated_at DATETIME2(0) NOT NULL CONSTRAINT DF_CATEGORIES_UPDATED_AT DEFAULT SYSDATETIME(),
    CONSTRAINT CK_CATEGORIES_STATUS CHECK (status IN ('ACTIVE','INACTIVE'))
);
GO

CREATE TABLE dbo.BRANDS (
    id INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_BRANDS PRIMARY KEY,
    slug VARCHAR(80) NOT NULL CONSTRAINT UQ_BRANDS_SLUG UNIQUE,
    name NVARCHAR(100) NOT NULL CONSTRAINT UQ_BRANDS_NAME UNIQUE,
    description NVARCHAR(500) NULL,
    logo_url NVARCHAR(500) NULL,
    created_at DATETIME2(0) NOT NULL CONSTRAINT DF_BRANDS_CREATED_AT DEFAULT SYSDATETIME()
);
GO

CREATE TABLE dbo.PRODUCTS (
    id INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_PRODUCTS PRIMARY KEY,
    slug VARCHAR(180) NOT NULL CONSTRAINT UQ_PRODUCTS_SLUG UNIQUE,
    name NVARCHAR(180) NOT NULL,
    description NVARCHAR(MAX) NULL,
    category_id INT NOT NULL,
    brand_id INT NOT NULL,
    base_price DECIMAL(18,2) NOT NULL,
    status VARCHAR(20) NOT NULL CONSTRAINT DF_PRODUCTS_STATUS DEFAULT 'ACTIVE',
    created_at DATETIME2(0) NOT NULL CONSTRAINT DF_PRODUCTS_CREATED_AT DEFAULT SYSDATETIME(),
    updated_at DATETIME2(0) NOT NULL CONSTRAINT DF_PRODUCTS_UPDATED_AT DEFAULT SYSDATETIME(),
    CONSTRAINT FK_PRODUCTS_CATEGORY FOREIGN KEY (category_id) REFERENCES dbo.CATEGORIES(id),
    CONSTRAINT FK_PRODUCTS_BRAND FOREIGN KEY (brand_id) REFERENCES dbo.BRANDS(id),
    CONSTRAINT CK_PRODUCTS_PRICE CHECK (base_price >= 0),
    CONSTRAINT CK_PRODUCTS_STATUS CHECK (status IN ('ACTIVE','INACTIVE'))
);
GO

CREATE TABLE dbo.PRODUCT_IMAGES (
    id BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_PRODUCT_IMAGES PRIMARY KEY,
    product_id INT NOT NULL,
    image_url NVARCHAR(500) NOT NULL,
    alt_text NVARCHAR(255) NULL,
    sort_order INT NOT NULL CONSTRAINT DF_PRODUCT_IMAGES_SORT DEFAULT 1,
    is_primary BIT NOT NULL CONSTRAINT DF_PRODUCT_IMAGES_PRIMARY DEFAULT 0,
    CONSTRAINT FK_PRODUCT_IMAGES_PRODUCT FOREIGN KEY (product_id) REFERENCES dbo.PRODUCTS(id),
    CONSTRAINT CK_PRODUCT_IMAGES_SORT CHECK (sort_order > 0)
);
GO

CREATE TABLE dbo.PRODUCT_VARIANTS (
    id BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_PRODUCT_VARIANTS PRIMARY KEY,
    product_id INT NOT NULL,
    size NVARCHAR(20) NOT NULL,
    color NVARCHAR(50) NOT NULL,
    sku VARCHAR(80) NOT NULL CONSTRAINT UQ_PRODUCT_VARIANTS_SKU UNIQUE,
    price_adjustment DECIMAL(18,2) NOT NULL CONSTRAINT DF_VARIANTS_PRICE_ADJ DEFAULT 0,
    image_url NVARCHAR(500) NULL,
    status VARCHAR(20) NOT NULL CONSTRAINT DF_VARIANTS_STATUS DEFAULT 'ACTIVE',
    CONSTRAINT FK_PRODUCT_VARIANTS_PRODUCT FOREIGN KEY (product_id) REFERENCES dbo.PRODUCTS(id),
    CONSTRAINT UQ_PRODUCT_VARIANTS_PRODUCT_SIZE_COLOR UNIQUE(product_id, size, color),
    CONSTRAINT CK_PRODUCT_VARIANTS_STATUS CHECK (status IN ('ACTIVE','INACTIVE'))
);
GO

CREATE TABLE dbo.STORE_INVENTORY (
    store_id INT NOT NULL,
    variant_id BIGINT NOT NULL,
    quantity INT NOT NULL CONSTRAINT DF_STORE_INVENTORY_QTY DEFAULT 0,
    updated_at DATETIME2(0) NOT NULL CONSTRAINT DF_STORE_INVENTORY_UPDATED_AT DEFAULT SYSDATETIME(),
    CONSTRAINT PK_STORE_INVENTORY PRIMARY KEY (store_id, variant_id),
    CONSTRAINT FK_STORE_INVENTORY_STORE FOREIGN KEY (store_id) REFERENCES dbo.STORES(store_id),
    CONSTRAINT FK_STORE_INVENTORY_VARIANT FOREIGN KEY (variant_id) REFERENCES dbo.PRODUCT_VARIANTS(id),
    CONSTRAINT CK_STORE_INVENTORY_QTY CHECK (quantity >= 0)
);
GO

CREATE TABLE dbo.PROMOTIONS (
    id INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_PROMOTIONS PRIMARY KEY,
    name NVARCHAR(120) NOT NULL,
    description NVARCHAR(500) NULL,
    discount_type VARCHAR(20) NOT NULL,
    discount_value DECIMAL(18,2) NOT NULL,
    starts_at DATETIME2(0) NOT NULL,
    ends_at DATETIME2(0) NOT NULL,
    status VARCHAR(20) NOT NULL CONSTRAINT DF_PROMOTIONS_STATUS DEFAULT 'ACTIVE',
    CONSTRAINT CK_PROMOTIONS_TYPE CHECK (discount_type IN ('PERCENT','FIXED')),
    CONSTRAINT CK_PROMOTIONS_VALUE CHECK (discount_value > 0),
    CONSTRAINT CK_PROMOTIONS_TIME CHECK (ends_at > starts_at),
    CONSTRAINT CK_PROMOTIONS_STATUS CHECK (status IN ('ACTIVE','INACTIVE'))
);
GO

CREATE TABLE dbo.PRODUCT_PROMOTIONS (
    product_id INT NOT NULL,
    promotion_id INT NOT NULL,
    CONSTRAINT PK_PRODUCT_PROMOTIONS PRIMARY KEY(product_id, promotion_id),
    CONSTRAINT FK_PRODUCT_PROMOTIONS_PRODUCT FOREIGN KEY (product_id) REFERENCES dbo.PRODUCTS(id),
    CONSTRAINT FK_PRODUCT_PROMOTIONS_PROMOTION FOREIGN KEY (promotion_id) REFERENCES dbo.PROMOTIONS(id)
);
GO

CREATE TABLE dbo.USER_ADDRESSES (
    id BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_USER_ADDRESSES PRIMARY KEY,
    user_email VARCHAR(100) NOT NULL,
    full_name NVARCHAR(100) NOT NULL,
    phone VARCHAR(20) NOT NULL,
    city NVARCHAR(100) NOT NULL,
    district NVARCHAR(100) NOT NULL,
    ward NVARCHAR(100) NOT NULL,
    address_line NVARCHAR(200) NOT NULL,
    note NVARCHAR(500) NULL,
    is_default BIT NOT NULL CONSTRAINT DF_USER_ADDRESSES_DEFAULT DEFAULT 0,
    created_at DATETIME2(0) NOT NULL CONSTRAINT DF_USER_ADDRESSES_CREATED_AT DEFAULT SYSDATETIME(),
    updated_at DATETIME2(0) NOT NULL CONSTRAINT DF_USER_ADDRESSES_UPDATED_AT DEFAULT SYSDATETIME(),
    CONSTRAINT FK_USER_ADDRESSES_USER FOREIGN KEY (user_email) REFERENCES dbo.USERS(email)
);
GO

CREATE TABLE dbo.WISHLIST_ITEMS (
    user_email VARCHAR(100) NOT NULL,
    product_id INT NOT NULL,
    created_at DATETIME2(0) NOT NULL CONSTRAINT DF_WISHLIST_CREATED_AT DEFAULT SYSDATETIME(),
    CONSTRAINT PK_WISHLIST_ITEMS PRIMARY KEY (user_email, product_id),
    CONSTRAINT FK_WISHLIST_USER FOREIGN KEY (user_email) REFERENCES dbo.USERS(email),
    CONSTRAINT FK_WISHLIST_PRODUCT FOREIGN KEY (product_id) REFERENCES dbo.PRODUCTS(id)
);
GO

CREATE TABLE dbo.CARTS (
    id BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_CARTS PRIMARY KEY,
    user_email VARCHAR(100) NOT NULL,
    status VARCHAR(20) NOT NULL CONSTRAINT DF_CARTS_STATUS DEFAULT 'ACTIVE',
    created_at DATETIME2(0) NOT NULL CONSTRAINT DF_CARTS_CREATED_AT DEFAULT SYSDATETIME(),
    updated_at DATETIME2(0) NOT NULL CONSTRAINT DF_CARTS_UPDATED_AT DEFAULT SYSDATETIME(),
    CONSTRAINT FK_CARTS_USER FOREIGN KEY (user_email) REFERENCES dbo.USERS(email),
    CONSTRAINT CK_CARTS_STATUS CHECK (status IN ('ACTIVE','ARCHIVED'))
);
GO

CREATE TABLE dbo.CART_ITEMS (
    id BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_CART_ITEMS PRIMARY KEY,
    cart_id BIGINT NOT NULL,
    product_id INT NOT NULL,
    variant_id BIGINT NOT NULL,
    store_id INT NOT NULL,
    quantity INT NOT NULL,
    selected BIT NOT NULL CONSTRAINT DF_CART_ITEMS_SELECTED DEFAULT 1,
    unit_price DECIMAL(18,2) NOT NULL,
    created_at DATETIME2(0) NOT NULL CONSTRAINT DF_CART_ITEMS_CREATED_AT DEFAULT SYSDATETIME(),
    updated_at DATETIME2(0) NOT NULL CONSTRAINT DF_CART_ITEMS_UPDATED_AT DEFAULT SYSDATETIME(),
    CONSTRAINT FK_CART_ITEMS_CART FOREIGN KEY (cart_id) REFERENCES dbo.CARTS(id),
    CONSTRAINT FK_CART_ITEMS_PRODUCT FOREIGN KEY (product_id) REFERENCES dbo.PRODUCTS(id),
    CONSTRAINT FK_CART_ITEMS_VARIANT FOREIGN KEY (variant_id) REFERENCES dbo.PRODUCT_VARIANTS(id),
    CONSTRAINT FK_CART_ITEMS_STORE FOREIGN KEY (store_id) REFERENCES dbo.STORES(store_id),
    CONSTRAINT UQ_CART_ITEMS_IDENTITY UNIQUE(cart_id, product_id, variant_id, store_id),
    CONSTRAINT CK_CART_ITEMS_QTY CHECK (quantity > 0),
    CONSTRAINT CK_CART_ITEMS_PRICE CHECK (unit_price >= 0)
);
GO

CREATE TABLE dbo.COUPONS (
    id INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_COUPONS PRIMARY KEY,
    code VARCHAR(50) NOT NULL CONSTRAINT UQ_COUPONS_CODE UNIQUE,
    name NVARCHAR(120) NOT NULL,
    description NVARCHAR(500) NULL,
    discount_type VARCHAR(20) NOT NULL,
    discount_value DECIMAL(18,2) NOT NULL,
    min_order_value DECIMAL(18,2) NOT NULL CONSTRAINT DF_COUPONS_MIN_ORDER DEFAULT 0,
    max_discount_value DECIMAL(18,2) NULL,
    usage_limit INT NULL,
    used_count INT NOT NULL CONSTRAINT DF_COUPONS_USED_COUNT DEFAULT 0,
    starts_at DATETIME2(0) NOT NULL,
    ends_at DATETIME2(0) NOT NULL,
    is_active BIT NOT NULL CONSTRAINT DF_COUPONS_ACTIVE DEFAULT 1,
    CONSTRAINT CK_COUPONS_TYPE CHECK (discount_type IN ('PERCENT','FIXED','FREESHIP')),
    CONSTRAINT CK_COUPONS_VALUE CHECK (discount_value >= 0),
    CONSTRAINT CK_COUPONS_MIN CHECK (min_order_value >= 0),
    CONSTRAINT CK_COUPONS_USAGE CHECK (usage_limit IS NULL OR usage_limit > 0),
    CONSTRAINT CK_COUPONS_TIME CHECK (ends_at > starts_at)
);
GO

CREATE TABLE dbo.ORDERS (
    id BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_ORDERS PRIMARY KEY,
    order_code VARCHAR(40) NOT NULL CONSTRAINT UQ_ORDERS_CODE UNIQUE,
    user_email VARCHAR(100) NOT NULL,
    status NVARCHAR(30) NOT NULL,
    recipient_name NVARCHAR(100) NOT NULL,
    recipient_phone VARCHAR(20) NOT NULL,
    shipping_address_line NVARCHAR(200) NOT NULL,
    shipping_ward NVARCHAR(100) NOT NULL,
    shipping_district NVARCHAR(100) NOT NULL,
    shipping_city NVARCHAR(100) NOT NULL,
    shipping_note NVARCHAR(500) NULL,
    payment_method VARCHAR(20) NOT NULL,
    coupon_id INT NULL,
    subtotal DECIMAL(18,2) NOT NULL,
    product_discount DECIMAL(18,2) NOT NULL CONSTRAINT DF_ORDERS_PRODUCT_DISCOUNT DEFAULT 0,
    shipping_fee DECIMAL(18,2) NOT NULL CONSTRAINT DF_ORDERS_SHIPPING_FEE DEFAULT 30000,
    coupon_discount DECIMAL(18,2) NOT NULL CONSTRAINT DF_ORDERS_COUPON_DISCOUNT DEFAULT 0,
    total DECIMAL(18,2) NOT NULL,
    created_at DATETIME2(0) NOT NULL CONSTRAINT DF_ORDERS_CREATED_AT DEFAULT SYSDATETIME(),
    updated_at DATETIME2(0) NOT NULL CONSTRAINT DF_ORDERS_UPDATED_AT DEFAULT SYSDATETIME(),
    CONSTRAINT FK_ORDERS_USER FOREIGN KEY (user_email) REFERENCES dbo.USERS(email),
    CONSTRAINT FK_ORDERS_COUPON FOREIGN KEY (coupon_id) REFERENCES dbo.COUPONS(id),
    CONSTRAINT CK_ORDERS_STATUS CHECK (status IN (N'Chờ xác nhận',N'Đã xác nhận',N'Đã giao',N'Đã hủy')),
    CONSTRAINT CK_ORDERS_PAYMENT_METHOD CHECK (payment_method IN ('COD','VNPAY','MOMO')),
    CONSTRAINT CK_ORDERS_MONEY CHECK (subtotal >= 0 AND product_discount >= 0 AND shipping_fee >= 0 AND coupon_discount >= 0 AND total >= 0)
);
GO

CREATE TABLE dbo.COUPON_USAGES (
    id BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_COUPON_USAGES PRIMARY KEY,
    coupon_id INT NOT NULL,
    user_email VARCHAR(100) NOT NULL,
    order_id BIGINT NOT NULL,
    used_at DATETIME2(0) NOT NULL CONSTRAINT DF_COUPON_USAGES_USED_AT DEFAULT SYSDATETIME(),
    CONSTRAINT FK_COUPON_USAGES_COUPON FOREIGN KEY (coupon_id) REFERENCES dbo.COUPONS(id),
    CONSTRAINT FK_COUPON_USAGES_USER FOREIGN KEY (user_email) REFERENCES dbo.USERS(email),
    CONSTRAINT FK_COUPON_USAGES_ORDER FOREIGN KEY (order_id) REFERENCES dbo.ORDERS(id)
);
GO

CREATE TABLE dbo.ORDER_ITEMS (
    id BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_ORDER_ITEMS PRIMARY KEY,
    order_id BIGINT NOT NULL,
    product_id INT NOT NULL,
    store_id INT NOT NULL,
    variant_id BIGINT NOT NULL,
    product_name NVARCHAR(180) NOT NULL,
    variant_name NVARCHAR(100) NOT NULL,
    image_url NVARCHAR(500) NULL,
    quantity INT NOT NULL,
    unit_price DECIMAL(18,2) NOT NULL,
    discount_amount DECIMAL(18,2) NOT NULL CONSTRAINT DF_ORDER_ITEMS_DISCOUNT DEFAULT 0,
    line_total DECIMAL(18,2) NOT NULL,
    CONSTRAINT FK_ORDER_ITEMS_ORDER FOREIGN KEY (order_id) REFERENCES dbo.ORDERS(id),
    CONSTRAINT FK_ORDER_ITEMS_PRODUCT FOREIGN KEY (product_id) REFERENCES dbo.PRODUCTS(id),
    CONSTRAINT FK_ORDER_ITEMS_STORE FOREIGN KEY (store_id) REFERENCES dbo.STORES(store_id),
    CONSTRAINT FK_ORDER_ITEMS_VARIANT FOREIGN KEY (variant_id) REFERENCES dbo.PRODUCT_VARIANTS(id),
    CONSTRAINT CK_ORDER_ITEMS_QTY CHECK (quantity > 0),
    CONSTRAINT CK_ORDER_ITEMS_MONEY CHECK (unit_price >= 0 AND discount_amount >= 0 AND line_total >= 0)
);
GO

CREATE TABLE dbo.PAYMENTS (
    id BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_PAYMENTS PRIMARY KEY,
    order_id BIGINT NOT NULL,
    method VARCHAR(20) NOT NULL,
    status VARCHAR(20) NOT NULL,
    transaction_ref VARCHAR(120) NULL,
    amount DECIMAL(18,2) NOT NULL,
    paid_at DATETIME2(0) NULL,
    created_at DATETIME2(0) NOT NULL CONSTRAINT DF_PAYMENTS_CREATED_AT DEFAULT SYSDATETIME(),
    CONSTRAINT FK_PAYMENTS_ORDER FOREIGN KEY (order_id) REFERENCES dbo.ORDERS(id),
    CONSTRAINT CK_PAYMENTS_METHOD CHECK (method IN ('COD','VNPAY','MOMO')),
    CONSTRAINT CK_PAYMENTS_STATUS CHECK (status IN ('PENDING','PAID','FAILED','REFUNDED')),
    CONSTRAINT CK_PAYMENTS_AMOUNT CHECK (amount >= 0)
);
GO

CREATE TABLE dbo.ORDER_STATUS_HISTORY (
    id BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_ORDER_STATUS_HISTORY PRIMARY KEY,
    order_id BIGINT NOT NULL,
    status NVARCHAR(30) NOT NULL,
    note NVARCHAR(500) NULL,
    created_at DATETIME2(0) NOT NULL,
    CONSTRAINT FK_ORDER_STATUS_HISTORY_ORDER FOREIGN KEY (order_id) REFERENCES dbo.ORDERS(id),
    CONSTRAINT CK_ORDER_STATUS_HISTORY_STATUS CHECK (status IN (N'Chờ xác nhận',N'Đã xác nhận',N'Đã giao',N'Đã hủy'))
);
GO

CREATE TABLE dbo.ORDER_CANCELLATIONS (
    id BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_ORDER_CANCELLATIONS PRIMARY KEY,
    order_id BIGINT NOT NULL,
    requested_by_email VARCHAR(100) NOT NULL,
    reason NVARCHAR(255) NOT NULL,
    other_reason NVARCHAR(500) NULL,
    status VARCHAR(30) NOT NULL CONSTRAINT DF_ORDER_CANCELLATIONS_STATUS DEFAULT 'PENDING',
    requested_at DATETIME2(0) NOT NULL,
    responded_at DATETIME2(0) NULL,
    response_note NVARCHAR(500) NULL,
    CONSTRAINT FK_ORDER_CANCELLATIONS_ORDER FOREIGN KEY (order_id) REFERENCES dbo.ORDERS(id),
    CONSTRAINT FK_ORDER_CANCELLATIONS_USER FOREIGN KEY (requested_by_email) REFERENCES dbo.USERS(email),
    CONSTRAINT CK_ORDER_CANCELLATIONS_STATUS CHECK (status IN ('PENDING','APPROVED','REJECTED'))
);
GO

CREATE TABLE dbo.REVIEWS (
    id BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_REVIEWS PRIMARY KEY,
    order_id BIGINT NOT NULL,
    order_item_id BIGINT NOT NULL,
    user_email VARCHAR(100) NOT NULL,
    product_id INT NOT NULL,
    rating INT NOT NULL,
    comment NVARCHAR(1000) NULL,
    status VARCHAR(20) NOT NULL CONSTRAINT DF_REVIEWS_STATUS DEFAULT 'APPROVED',
    created_at DATETIME2(0) NOT NULL CONSTRAINT DF_REVIEWS_CREATED_AT DEFAULT SYSDATETIME(),
    updated_at DATETIME2(0) NOT NULL CONSTRAINT DF_REVIEWS_UPDATED_AT DEFAULT SYSDATETIME(),
    CONSTRAINT FK_REVIEWS_ORDER FOREIGN KEY (order_id) REFERENCES dbo.ORDERS(id),
    CONSTRAINT FK_REVIEWS_ORDER_ITEM FOREIGN KEY (order_item_id) REFERENCES dbo.ORDER_ITEMS(id),
    CONSTRAINT FK_REVIEWS_USER FOREIGN KEY (user_email) REFERENCES dbo.USERS(email),
    CONSTRAINT FK_REVIEWS_PRODUCT FOREIGN KEY (product_id) REFERENCES dbo.PRODUCTS(id),
    CONSTRAINT UQ_REVIEWS_USER_PRODUCT UNIQUE(user_email, product_id),
    CONSTRAINT CK_REVIEWS_RATING CHECK (rating BETWEEN 1 AND 5),
    CONSTRAINT CK_REVIEWS_STATUS CHECK (status IN ('PENDING','APPROVED','HIDDEN'))
);
GO

