-- SEED: PRODUCTS (45 rows from supplied dataset)
SET IDENTITY_INSERT dbo.PRODUCTS ON;
INSERT INTO dbo.PRODUCTS(id,slug,name,description,category_id,brand_id,base_price,status,created_at,updated_at) VALUES
(1,N'nike-air-force-1-07',N'Nike Air Force 1 ''07',N'Nike Air Force 1 ''07 sở hữu thiết kế cổ thấp tối giản, mang đậm phong cách streetwear cổ điển. Thân giày làm từ da mịn bền bỉ, kết hợp công nghệ đệm Nike Air ẩn mang lại cảm giác êm ái khi di chuyển. Mũi giày thoáng khí cùng đế cao su bám đường tốt giúp đôi giày vừa thoải mái, vừa linh hoạt phối với mọi trang phục hàng ngày.',1,1,2929000.00,'ACTIVE',N'2026-09-01 09:00:00',N'2026-09-01 09:00:00'),
(2,N'nike-air-max-90',N'Nike Air Max 90',N'Nike Air Max 90 sở hữu thiết kế cổ điển vượt thời gian với điểm nhấn cửa sổ đệm Air nổi bật ở gót. Nhờ công nghệ đệm khí êm ái tối ưu, đôi sneaker này không chỉ đem lại cảm giác thoải mái suốt ngày dài mà còn tôn lên phong cách thể thao năng động, cực kỳ linh hoạt khi phối cùng mọi trang phục.',1,1,3519000.00,'ACTIVE',N'2026-09-01 10:00:00',N'2026-09-01 10:00:00'),
(3,N'nike-dunk-low',N'Nike Dunk Low',N'Nike Dunk Low sở hữu kiểu dáng bóng rổ đường phố kinh điển với phối màu đa dạng. Thân giày làm từ da cao cấp bền bỉ, kết hợp cổ thấp linh hoạt và đế cao su bám đường tốt, mang đến phong cách trẻ trung, năng động và cực kỳ dễ phối đồ.',1,1,2929000.00,'ACTIVE',N'2026-09-01 11:00:00',N'2026-09-01 11:00:00'),
(4,N'nike-blazer-mid-77',N'Nike Blazer Mid ''77',N'Nike Blazer Mid ''77 sở hữu phong cách cổ cao vintage vượt thời gian với chất liệu da bền bỉ và chi tiết da lộn tinh tế. Thiết kế tối giản, đậm chất retro giúp đôi sneaker này vừa cá tính, vừa cực kỳ linh hoạt khi phối cùng mọi trang phục streetstyle.',1,1,2890000.00,'ACTIVE',N'2026-09-01 12:00:00',N'2026-09-01 12:00:00'),
(5,N'nike-pegasus-40',N'Nike Pegasus 40',N'Nike Pegasus 40 sở hữu thiết kế thể thao hiện đại, tối ưu cho chạy bộ hàng ngày. Thân giày vải lưới thoáng khí kết hợp công nghệ đệm React và Zoom Air mang lại độ phản hồi lực cao, êm ái và vô cùng bền bỉ.',1,1,3829000.00,'ACTIVE',N'2026-09-02 13:00:00',N'2026-09-02 13:00:00'),
(6,N'adidas-ultraboost-light',N'Adidas Ultraboost Light',N'Adidas Ultraboost Light sở hữu công nghệ đệm Light BOOST thế hệ mới nhẹ hơn 30%, mang lại độ phản hồi lực vượt trội. Thân giày Primeknit+ ôm sát thoáng khí cùng đế cao su Continental™ bám đường tốt, tối ưu cho mọi cự ly chạy.',1,2,2500000.00,'ACTIVE',N'2026-09-02 09:00:00',N'2026-09-02 09:00:00'),
(7,N'adidas-samba-og',N'Adidas Samba OG',N'Adidas Samba OG sở hữu kiểu dáng bóng đá trong nhà kinh điển, đậm chất phong cách streetwear hot trend. Thân giày làm từ da cao cấp kết hợp mũi giày da lộn tinh tế và đế cao su gum bám đường, vô cùng dễ phối đồ.',1,2,2700000.00,'ACTIVE',N'2026-09-02 10:00:00',N'2026-09-02 10:00:00'),
(8,N'adidas-gazelle',N'Adidas Gazelle',N'Adidas Gazelle sở hữu kiểu dáng cổ điển vượt thời gian với chất liệu da lộn mềm mại đặc trưng. Thiết kế 3 sọc tối giản, tinh tế giúp đôi sneaker này vừa thanh lịch, vừa dễ dàng phối cùng nhiều phong cách trang phục hàng ngày.',1,2,2500000.00,'ACTIVE',N'2026-09-02 11:00:00',N'2026-09-02 11:00:00'),
(9,N'adidas-stan-smith',N'Adidas Stan Smith',N'Adidas Stan Smith sở hữu thiết kế tennis biểu tượng với phong cách tối giản vượt thời gian. Thân giày da mượt mà kết hợp chi tiết đục lỗ 3 sọc thoáng khí, mang lại vẻ thanh lịch và vô cùng dễ phối đồ.',1,2,2400000.00,'ACTIVE',N'2026-09-03 12:00:00',N'2026-09-03 12:00:00'),
(10,N'adidas-superstar',N'Adidas Superstar',N'Adidas Superstar sở hữu thiết kế mũi vỏ sò (Shell-toe) biểu tượng mang đậm chất văn hóa Hip-hop. Thân giày da bền bỉ kết hợp chi tiết 3 sọc kinh điển, mang đến phong cách cá tính, năng động và vô cùng dễ phối đồ.',1,2,2600000.00,'ACTIVE',N'2026-09-03 13:00:00',N'2026-09-03 13:00:00'),
(11,N'new-balance-574',N'New Balance 574',N'New Balance 574 sở hữu thiết kế retro cổ điển đặc trưng với sự kết hợp giữa chất liệu da lộn và vải lưới cao cấp. Đệm ENCAMP nâng đỡ tối ưu, đem lại sự êm ái, bền bỉ và vô cùng dễ phối đồ hàng ngày.',1,3,2495000.00,'ACTIVE',N'2026-09-03 09:00:00',N'2026-09-03 09:00:00'),
(12,N'new-balance-530',N'New Balance 530',N'New Balance 530 sở hữu thiết kế Retro Running thập niên 2000 năng động, cá tính. Thân giày vải lưới thoáng khí phối chi tiết ánh kim nổi bật, kết hợp công nghệ đệm ABZORB êm ái, mang lại sự thoải mái tối đa khi mang hàng ngày.',1,3,2850000.00,'ACTIVE',N'2026-09-03 10:00:00',N'2026-09-03 10:00:00'),
(13,N'new-balance-2002r',N'New Balance 2002R',N'New Balance 2002R sở hữu phong cách Dad Sneaker hiện đại với chất liệu da lộn cao cấp kết hợp vải lưới thoáng khí. Công nghệ đệm N-ergy và ABZORB vượt trội mang lại cảm giác vô cùng êm ái, nâng đỡ tối đa khi di chuyển hàng ngày.',1,3,3850000.00,'ACTIVE',N'2026-09-04 11:00:00',N'2026-09-04 11:00:00'),
(14,N'new-balance-550',N'New Balance 550',N'New Balance 550 sở hữu kiểu dáng bóng rổ thập niên 80 retro đầy sức hút. Thân giày da cao cấp bền bỉ kết hợp đế cao su bám đường tốt, mang lại phong cách cổ điển, trẻ trung và cực kỳ dễ phối đồ.',1,3,3250000.00,'ACTIVE',N'2026-09-04 12:00:00',N'2026-09-04 12:00:00'),
(15,N'new-balance-9060',N'New Balance 9060',N'New Balance 9060 sở hữu thiết kế đế hầm hố phá cách, lấy cảm hứng từ phong cách Y2K độc đáo. Sự kết hợp giữa da lộn cao cấp, vải lưới và công nghệ đệm ABZORB mang lại cảm giác cực kỳ êm ái, nâng đỡ tối đa.',1,3,4200000.00,'ACTIVE',N'2026-09-04 13:00:00',N'2026-09-04 13:00:00'),
(16,N'teva-hurricane-xlt2',N'Teva Hurricane XLT2',N'Teva Hurricane XLT2 sở hữu kiểu dáng sandal dã ngoại khỏe khoắn với quai đai nhanh khô làm từ nhựa tái chế bền bỉ. Đế cao su bám địa hình tốt kết hợp lớp đệm EVA êm ái, tối ưu cho các hoạt động di chuyển, phượt và lội nước.',2,4,1850000.00,'ACTIVE',N'2026-09-04 09:00:00',N'2026-09-04 09:00:00'),
(17,N'teva-original-universal',N'Teva Original Universal',N'Teva Original Universal sở hữu thiết kế biểu tượng tối giản với hệ thống quai dán tiện lợi làm từ nhựa tái chế nhanh khô. Đế cao su bám đường tốt kết hợp đệm xốp EVA nhẹ nhàng, tối ưu cho sự thoải mái khi mang hàng ngày hay dã ngoại.',2,4,1350000.00,'ACTIVE',N'2026-09-05 10:00:00',N'2026-09-05 10:00:00'),
(18,N'teva-universal-trail',N'Teva Universal Trail',N'Teva Universal Trail sở hữu thiết kế sandal outdoor hiện đại với quai đai làm từ nhựa tái chế Unifi® bền bỉ, nhanh khô. Đế ngoài Vibram® Megagrip cao cấp bám dính vượt trội cùng đệm EVA êm ái, tối ưu cho các chuyến leo núi, trekking và lội suối.',2,4,2250000.00,'ACTIVE',N'2026-09-05 11:00:00',N'2026-09-05 11:00:00'),
(19,N'teva-midform-universal',N'Teva Midform Universal',N'Teva Midform Universal sở hữu thiết kế đế xuồng (platform) cao 3cm thời trang, giúp tôn dáng nhẹ nhàng. Quai dán tiện lợi làm từ nhựa tái chế Unifi® nhanh khô, kết hợp đệm xốp EVA nhẹ êm, mang lại sự trẻ trung, cá tính và thoải mái cho phái đẹp khi mang hàng ngày.',2,4,1650000.00,'ACTIVE',N'2026-09-05 12:00:00',N'2026-09-05 12:00:00'),
(20,N'teva-terra-fi-5-universal',N'Teva Terra Fi 5 Universal',N'Teva Terra Fi 5 Universal sở hữu thiết kế sandal outdoor phượt đỉnh cao với khả năng chịu lực vượt trội. Hệ thống quai đai nhanh khô kết hợp đệm lót EVA siêu êm và đế cao su bám địa hình ưu việt, mang lại sự nâng đỡ tối đa cho các chuyến hành trình dài.',2,4,2450000.00,'ACTIVE',N'2026-09-05 13:00:00',N'2026-09-05 13:00:00'),
(21,N'birkenstock-arizona-birko-flor',N'Birkenstock Arizona Birko-Flor',N'Birkenstock Arizona Birko-Flor sở hữu thiết kế 2 quai khóa biểu tượng mang phong cách tối giản, cá tính. Thân giày làm từ chất liệu da tổng hợp Birko-Flor® thân thiện với làn da, kết hợp đế bần tự nhiên thiết kế chuẩn nhân trắc học ôm sát phom chân, mang lại sự nâng đỡ và thoải mái tối đa.',2,5,2600000.00,'ACTIVE',N'2026-09-06 09:00:00',N'2026-09-06 09:00:00'),
(22,N'birkenstock-milano',N'Birkenstock Milano',N'Birkenstock Milano sở hữu thiết kế 3 quai khóa chắc chắn (gồm 2 quai ngang và 1 quai hậu) mang lại khả năng cố định chân tối ưu. Thân giày làm từ chất liệu cao cấp kết hợp đế bần tự nhiên thiết kế chuẩn nhân trắc học, mang lại sự nâng đỡ vượt trội và cực kỳ thoải mái cho những chuyến di chuyển dài.',2,5,2900000.00,'ACTIVE',N'2026-09-06 10:00:00',N'2026-09-06 10:00:00'),
(23,N'birkenstock-mayari',N'Birkenstock Mayari',N'Birkenstock Mayari sở hữu thiết kế xỏ ngón đan chéo thanh lịch với 2 quai khóa tùy chỉnh mang lại vẻ đẹp nữ tính, hiện đại. Thân giày làm từ chất liệu cao cấp kết hợp đế bần tự nhiên thiết kế chuẩn nhân trắc học, giúp ôm sát phom chân và mang lại sự êm ái, thoáng mát suốt ngày dài.',2,5,2500000.00,'ACTIVE',N'2026-09-06 11:00:00',N'2026-09-06 11:00:00'),
(24,N'birkenstock-arizona-eva',N'Birkenstock Arizona EVA',N'Birkenstock Arizona EVA sở hữu thiết kế 2 quai khóa đúc liền nguyên khối thời trang, hiện đại. Được làm hoàn toàn từ chất liệu nhựa EVA siêu nhẹ, chống nước 100% và cực kỳ dễ vệ sinh, sản phẩm giữ nguyên phom dáng chuẩn nhân trắc học ôm sát vòm chân, mang lại cảm giác êm ái, linh hoạt, rất thích hợp cho đi biển, đi mưa hay mang hàng ngày.',2,5,1300000.00,'ACTIVE',N'2026-09-06 12:00:00',N'2026-09-06 12:00:00'),
(25,N'birkenstock-boston-clog',N'Birkenstock Boston Clog',N'Birkenstock Boston Clog sở hữu thiết kế dép sục bít mũi (clog) cổ điển, mang phong cách thanh lịch và tối giản. Thân giày làm từ chất liệu da lộn (suede) mềm mại cao cấp, kết hợp đế bần tự nhiên thiết kế chuẩn nhân trắc học ôm sát bàn chân, mang lại cảm giác vô cùng êm ái, ấm áp và thoải mái suốt 4 mùa.',2,5,3500000.00,'ACTIVE',N'2026-09-07 13:00:00',N'2026-09-07 13:00:00'),
(26,N'crocs-classic-all-terrain-sandal',N'Crocs Classic All-Terrain Sandal',N'Crocs Classic All-Terrain Sandal sở hữu thiết kế sandal quai hậu năng động với phần đế ngoài đúc rãnh sâu bám đường cực tốt. Quai đeo gót tùy chỉnh linh hoạt kết hợp chất liệu xốp Croslite™ chống nước, siêu nhẹ và dễ vệ sinh, tối ưu cho các chuyến dã ngoại, du lịch và hoạt động ngoài trời.',2,6,1395000.00,'ACTIVE',N'2026-09-07 09:00:00',N'2026-09-07 09:00:00'),
(27,N'crocs-classic-cozzzy-sandal',N'Crocs Classic Cozzzy Sandal',N'Crocs Classic Cozzzy Sandal sở hữu thiết kế 2 quai ngang thời trang kết hợp lớp lót lông xù (plush liner) siêu mềm mại, ấm áp. Làm từ chất liệu xốp Croslite™ nhẹ êm và đệm đế nâng cao, sản phẩm mang lại cảm giác cực kỳ thoải mái, thích hợp mang trong nhà lẫn dạo phố mùa lạnh.',2,6,1295000.00,'ACTIVE',N'2026-09-07 10:00:00',N'2026-09-07 10:00:00'),
(28,N'crocs-brooklyn-low-wedge',N'Crocs Brooklyn Low Wedge',N'Crocs Brooklyn Low Wedge sở hữu thiết kế đế xuồng thời trang với độ cao vừa phải, giúp tôn dáng tự nhiên và nâng tầm phong cách. Sử dụng đệm xốp LiteRide™ siêu mềm kết hợp phần quai TPU dẻo nhẹ, ôm chân, sản phẩm mang lại cảm giác êm ái vượt trội, thoải mái suốt cả ngày dài năng động.',2,6,1895000.00,'ACTIVE',N'2026-09-07 11:00:00',N'2026-09-07 11:00:00'),
(29,N'crocs-swiftwater-expedition',N'Crocs Swiftwater Expedition',N'Crocs Swiftwater Expedition sở hữu thiết kế sandal phượt dã ngoại khỏe khoắn với hệ thống quai dán TPU mềm mại, linh hoạt tùy chỉnh. Được chế tạo từ chất liệu xốp Croslite™ siêu nhẹ, chống nước và không bám bẩn, kết hợp phần đế đúc rãnh sâu bám đường tốt, sản phẩm mang lại sự êm ái và an toàn cho các chuyến du lịch, lội suối và hoạt động ngoài trời.',2,6,1495000.00,'ACTIVE',N'2026-09-08 12:00:00',N'2026-09-08 12:00:00'),
(30,N'crocs-classic-mega-crush-sandal',N'Crocs Classic Mega Crush Sandal',N'Crocs Classic Mega Crush Sandal sở hữu thiết kế đế xuồng hầm hố ấn tượng với độ cao lên tới 6.13cm, giúp tôn dáng tối đa và tạo điểm nhấn thời trang cực kỳ cá tính. Làm từ chất liệu xốp Croslite™ đúc nguyên khối siêu nhẹ, chống nước, kết hợp phần quai dép có các lỗ gắn phụ kiện Jibbitz™ độc đáo, sản phẩm mang lại cảm giác êm ái, bám đường tốt và đầy trẻ trung.',2,6,2395000.00,'ACTIVE',N'2026-09-08 13:00:00',N'2026-09-08 13:00:00'),
(31,N'puma-deviate-nitro-3',N'Puma Deviate Nitro 3',N'Puma Deviate Nitro 3 sở hữu thiết kế siêu nhẹ, chuyên dụng cho các buổi chạy tốc độ và marathon. Trang bị lớp bọt đệm NITROFOAM™ Elite cực kỳ nảy kết hợp đĩa đệm Carbon PWRPLATE vượt trội, sản phẩm mang lại khả năng phản hồi lực tối đa, hỗ trợ tăng tốc vượt bậc và tối ưu năng lượng trên mọi quãng đường.',3,7,3950000.00,'ACTIVE',N'2026-09-08 09:00:00',N'2026-09-08 09:00:00'),
(32,N'puma-future-7-match-tt',N'Puma Future 7 Match TT',N'Puma Future 7 Match TT sở hữu thiết kế đinh dăm chuyên dụng cho sân cỏ nhân tạo với chất liệu quai mềm mại, co giãn tốt. Công nghệ dệt thích ứng FUZIONFIT+ kết hợp các chi tiết in nổi ở vùng tiếp xúc bóng giúp ôm sát bàn chân, tăng cường khả năng kiểm soát và tối ưu độ bám cho những pha xử lý bóng linh hoạt.',3,7,2100000.00,'ACTIVE',N'2026-09-08 10:00:00',N'2026-09-08 10:00:00'),
(33,N'puma-ultra-ultimate-tt',N'Puma Ultra Ultimate TT',N'Puma Ultra Ultimate TT sở hữu thiết kế siêu nhẹ dành cho các cầu thủ ưu tiên tốc độ trên sân cỏ nhân tạo. Thân giày ứng dụng công nghệ dệt ULTRAWEAVE siêu mỏng kết hợp khung gia cố PWRTAPE ôm sát chân, đi cùng đế đinh dăm rubber cao cấp bám sân linh hoạt, hỗ trợ tối đa cho các bứt tốc và đổi hướng đột ngột.',3,7,3500000.00,'ACTIVE',N'2026-09-09 11:00:00',N'2026-09-09 11:00:00'),
(34,N'puma-pwrframe-tr-2',N'Puma PWRFrame TR 2',N'Puma PWRFrame TR 2 sở hữu thiết kế chuyên dụng cho các bài tập đa năng (Cross-training) và HIIT với độ ổn định cao. Trang bị công nghệ khung PWRFRAME siêu mỏng hỗ trợ cố định bàn chân trong các chuyển động đa hướng, kết hợp đệm bọt PROFOAM EVA êm ái và đế cao su PUMAGRIP bám sàn vượt trội, mang lại sự vững chắc và tự tin tối đa cho mọi buổi tập luyện cường độ cao.',3,7,2700000.00,'ACTIVE',N'2026-09-09 12:00:00',N'2026-09-09 12:00:00'),
(35,N'puma-mb-03-basketball',N'Puma MB.03 Basketball',N'Puma MB.03 Basketball sở hữu thiết kế độc bản đậm chất cá tính của siêu sao LaMelo Ball với các đường cắt xẻ táo bạo và phối màu bắt mắt. Trang bị công nghệ bọt đệm NITRO™ bơm khí N2 cao cấp phủ suốt đế giữa mang lại khả năng hoàn trả năng lượng tối đa, kết hợp đế cao su bám sàn chống trượt vượt trội, hỗ trợ tối đa cho các pha bứt tốc và xoay xở linh hoạt trên sân bóng rổ.',3,7,3800000.00,'ACTIVE',N'2026-09-09 13:00:00',N'2026-09-09 13:00:00'),
(36,N'under-armour-curry-11',N'Under Armour Curry 11',N'Under Armour Curry 11 sở hữu thiết kế cổ thấp linh hoạt, tối ưu cho lối chơi tốc độ và dứt điểm nhanh của Stephen Curry. Được trang bị công nghệ đệm kép UA Flow hai mật độ siêu nhẹ và không cần đế cao su, sản phẩm mang lại độ bám sàn vượt trội, độ phản hồi lực cực nhạy cùng phần thân dệt Warp™ ôm sát cố định bàn chân tuyệt đối trong mọi tình huống đổi hướng.',3,8,3900000.00,'ACTIVE',N'2026-09-09 09:00:00',N'2026-09-09 09:00:00'),
(37,N'under-armour-hovr-phantom-3',N'Under Armour HOVR Phantom 3',N'Under Armour HOVR Phantom 3 sở hữu thiết kế cổ chun ôm sát như một chiếc tất (sock-like fit), mang phong cách thể thao hiện đại và mạnh mẽ. Trang bị đệm bọt UA HOVR™ hoàn trả năng lượng tối đa kết hợp phần lót giày Molded Midfoot Panel hỗ trợ cố định mu bàn chân, sản phẩm mang lại cảm giác êm ái vượt trội, thoáng khí và cực kỳ vững chắc cho các buổi chạy bộ lẫn tập luyện hàng ngày.',3,8,4299000.00,'ACTIVE',N'2026-09-10 10:00:00',N'2026-09-10 10:00:00'),
(38,N'under-armour-tribase-reign-5',N'Under Armour TriBase Reign 5',N'Under Armour TriBase Reign 5 sở hữu thiết kế chuyên dụng cho các bài tập cường độ cao (HIIT) và nâng tạ heavy-duty. Trang bị công nghệ đế độc quyền UA TriBase™ giúp tối đa hóa khả năng tiếp xúc mặt sàn, hỗ trợ lực bám vững chắc và tối ưu chuyển động tự nhiên của bàn chân, kết hợp đệm bọt Micro G® êm ái, mang lại độ ổn định tuyệt đối cho mọi buổi tập luyện bứt phá.',3,8,3500000.00,'ACTIVE',N'2026-09-10 11:00:00',N'2026-09-10 11:00:00'),
(39,N'under-armour-velociti-3',N'Under Armour Velociti 3',N'Under Armour Velociti 3 sở hữu thiết kế cổ thấp siêu nhẹ với thân giày dệt Flat Knit co giãn, thoáng khí vượt trội và ôm sát bàn chân theo từng chuyển động. Chế tạo trên nền tảng đệm bọt liền khối UA Flow loại bỏ hoàn toàn phần đế cao su truyền thống, sản phẩm mang lại độ bám sàn kinh ngạc, cảm giác tiếp đất mượt mà và khả năng phản hồi lực cực nhạy cho các buổi chạy tốc độ.',3,8,3599000.00,'ACTIVE',N'2026-09-10 12:00:00',N'2026-09-10 12:00:00'),
(40,N'under-armour-project-rock-6',N'Under Armour Project Rock 6',N'Under Armour Project Rock 6 sở hữu thiết kế cổ trung hầm hố, chuẩn mực cho các bài tập thể hình và huấn luyện sức mạnh cường độ cao cùng Dwayne "The Rock" Johnson. Trang bị đệm bọt UA HOVR™ hoàn trả năng lượng tối đa kết hợp công nghệ đế UA TriBase™ tối ưu hóa diện tích tiếp xúc mặt sàn, sản phẩm mang lại độ ổn định vững chắc, bám sàn vượt trội và độ bền bỉ tuyệt đối trong từng hiệp tập.',3,8,3999000.00,'ACTIVE',N'2026-09-10 13:00:00',N'2026-09-10 13:00:00'),
(41,N'asics-gel-kayano-30',N'Asics Gel-Kayano 30',N'Asics Gel-Kayano 30 sở hữu thiết kế hỗ trợ chống lật trong với công nghệ 4D GUIDANCE SYSTEM™. Kết hợp đệm FF BLAST™ PLUS ECO và PureGEL™ gót chân, giày mang lại độ êm ái vượt trội và nâng đỡ tối ưu.',3,9,4599000.00,'ACTIVE',N'2026-09-11 09:00:00',N'2026-09-11 09:00:00'),
(42,N'asics-gel-resolution-9',N'Asics Gel-Resolution 9',N'Asics Gel-Resolution 9 sở hữu thiết kế chuyên dụng cho tennis và pickleball, nổi bật với công nghệ DYNAWALL™ và DYNAWRAP™ tối ưu độ ổn định khi di chuyển ngang. Kết hợp đệm GEL™ êm ái cùng đế AHARPLUS™ siêu bền, sản phẩm mang lại sự bảo vệ và bám sân vượt trội.',3,9,3799000.00,'ACTIVE',N'2026-09-11 10:00:00',N'2026-09-11 10:00:00'),
(43,N'asics-novablast-4',N'Asics Novablast 4',N'Asics Novablast 4 sở hữu thiết kế đế xuồng trampoline độc đáo. Đệm FF BLAST™ PLUS ECO siêu nhẹ và đàn hồi giúp tối ưu phản hồi lực, mang lại bước chạy bùng nổ cho các buổi chạy hàng ngày.',3,9,3729000.00,'ACTIVE',N'2026-09-11 11:00:00',N'2026-09-11 11:00:00'),
(44,N'asics-court-ff-3',N'Asics Court FF 3',N'Asics Court FF 3 sở hữu thiết kế hỗ trợ chuyển động linh hoạt cho tennis và pickleball. Trang bị đệm FLYTEFOAM™ kết hợp GEL™ gót chân cùng công nghệ TWISTRUSS™ giúp tăng tốc và đổi hướng bứt phá.',3,9,4399000.00,'ACTIVE',N'2026-09-11 12:00:00',N'2026-09-11 12:00:00'),
(45,N'asics-gel-rocket-11',N'Asics Gel-Rocket 11',N'Asics Gel-Rocket 11 sở hữu thiết kế đa năng tối ưu cho bóng chuyền và cầu lông. Được trang bị đệm GEL™ giảm chấn cùng công nghệ TRUSSTIC™ tăng độ ổn định, sản phẩm mang lại sự linh hoạt và bám sân vượt trội.',3,9,1899000.00,'ACTIVE',N'2026-09-12 13:00:00',N'2026-09-12 13:00:00');
