-- INDEXES
CREATE UNIQUE INDEX UX_STORES_MANAGER_EMAIL ON dbo.STORES(manager_email) WHERE manager_email IS NOT NULL;
GO
CREATE INDEX IX_PRODUCTS_CATEGORY_STATUS ON dbo.PRODUCTS(category_id,status);
GO
CREATE INDEX IX_PRODUCTS_BRAND_STATUS ON dbo.PRODUCTS(brand_id,status);
GO
CREATE INDEX IX_PRODUCT_IMAGES_PRODUCT ON dbo.PRODUCT_IMAGES(product_id,is_primary,sort_order);
GO
CREATE INDEX IX_PRODUCT_VARIANTS_PRODUCT ON dbo.PRODUCT_VARIANTS(product_id,status);
GO
CREATE INDEX IX_STORE_INVENTORY_STORE_QTY ON dbo.STORE_INVENTORY(store_id,quantity);
GO
CREATE INDEX IX_ORDERS_USER_CREATED_AT ON dbo.ORDERS(user_email,created_at DESC);
GO
CREATE INDEX IX_ORDER_ITEMS_ORDER ON dbo.ORDER_ITEMS(order_id);
GO
CREATE INDEX IX_ORDER_STATUS_HISTORY_ORDER_CREATED_AT ON dbo.ORDER_STATUS_HISTORY(order_id,created_at);
GO
CREATE INDEX IX_REVIEWS_PRODUCT_STATUS ON dbo.REVIEWS(product_id,status);
GO
CREATE INDEX IX_CART_ITEMS_CART ON dbo.CART_ITEMS(cart_id);
GO
CREATE INDEX IX_WISHLIST_USER ON dbo.WISHLIST_ITEMS(user_email,created_at DESC);
GO

-- QUICK VALIDATION
SELECT COUNT(*) AS store_count FROM dbo.STORES;
SELECT COUNT(*) AS category_count FROM dbo.CATEGORIES;
SELECT COUNT(*) AS brand_count FROM dbo.BRANDS;
SELECT COUNT(*) AS product_count FROM dbo.PRODUCTS;
SELECT COUNT(*) AS variant_count FROM dbo.PRODUCT_VARIANTS;
SELECT COUNT(*) AS inventory_rows FROM dbo.STORE_INVENTORY;
SELECT COUNT(*) AS order_count FROM dbo.ORDERS;
SELECT status, COUNT(*) AS order_count FROM dbo.ORDERS GROUP BY status ORDER BY status;
SELECT p.id,p.name,p.base_price,AVG(CAST(r.rating AS DECIMAL(3,2))) AS rating_average,SUM(CASE WHEN o.status=N'Đã giao' THEN oi.quantity ELSE 0 END) AS sold_quantity FROM dbo.PRODUCTS p LEFT JOIN dbo.REVIEWS r ON r.product_id=p.id AND r.status='APPROVED' LEFT JOIN dbo.ORDER_ITEMS oi ON oi.product_id=p.id LEFT JOIN dbo.ORDERS o ON o.id=oi.order_id GROUP BY p.id,p.name,p.base_price ORDER BY p.id;
GO


-- ============================================================================
-- C15 / CODEX STATIC-DATA VALIDATION
-- Non-mutating checks only.
-- ============================================================================

-- Expected canonical table count.
SELECT COUNT(*) AS canonical_table_count
FROM sys.tables
WHERE name IN (
    'ROLES','USERS','USER_ROLES','OTP_VERIFICATIONS','PASSWORD_RESET_TOKENS',
    'STORES','CATEGORIES','BRANDS','PRODUCTS','PRODUCT_IMAGES',
    'PRODUCT_VARIANTS','STORE_INVENTORY','PROMOTIONS','PRODUCT_PROMOTIONS',
    'USER_ADDRESSES','WISHLIST_ITEMS','CARTS','CART_ITEMS','COUPONS',
    'COUPON_USAGES','ORDERS','ORDER_ITEMS','PAYMENTS',
    'ORDER_STATUS_HISTORY','ORDER_CANCELLATIONS','REVIEWS'
);

-- Image paths must all point to the temporary in-project asset.
SELECT 'PRODUCT_IMAGES' AS source_table, COUNT(*) AS wrong_path_count
FROM dbo.PRODUCT_IMAGES
WHERE image_url <> N'/images/storefront/products/T-Winkle.png'
UNION ALL
SELECT 'PRODUCT_VARIANTS', COUNT(*)
FROM dbo.PRODUCT_VARIANTS
WHERE image_url IS NOT NULL
  AND image_url <> N'/images/storefront/products/T-Winkle.png'
UNION ALL
SELECT 'STORES', COUNT(*)
FROM dbo.STORES
WHERE image_url IS NOT NULL
  AND image_url <> N'/images/storefront/stores/T-Winkle.png'
UNION ALL
SELECT 'CATEGORIES', COUNT(*)
FROM dbo.CATEGORIES
WHERE image_url IS NOT NULL
  AND image_url <> N'/images/storefront/categories/T-Winkle.png'
UNION ALL
SELECT 'BRANDS', COUNT(*)
FROM dbo.BRANDS
WHERE logo_url IS NOT NULL
  AND logo_url <> N'/images/storefront/brands/T-Winkle.png'
UNION ALL
SELECT 'ORDER_ITEMS', COUNT(*)
FROM dbo.ORDER_ITEMS
WHERE image_url IS NOT NULL
  AND image_url <> N'/images/storefront/products/T-Winkle.png';

-- Canonical statuses/types.
SELECT 'PAYMENT_INVALID_STATUS' AS check_name, COUNT(*) AS violations
FROM dbo.PAYMENTS
WHERE status NOT IN ('PENDING','PAID','FAILED','REFUNDED')
UNION ALL
SELECT 'STORE_INVALID_STATUS', COUNT(*)
FROM dbo.STORES
WHERE status NOT IN ('OPEN','CLOSED')
UNION ALL
SELECT 'PRODUCT_INVALID_STATUS', COUNT(*)
FROM dbo.PRODUCTS
WHERE status NOT IN ('ACTIVE','INACTIVE')
UNION ALL
SELECT 'VARIANT_INVALID_STATUS', COUNT(*)
FROM dbo.PRODUCT_VARIANTS
WHERE status NOT IN ('ACTIVE','INACTIVE')
UNION ALL
SELECT 'ORDER_INVALID_STATUS', COUNT(*)
FROM dbo.ORDERS
WHERE status NOT IN (N'Chờ xác nhận',N'Đã xác nhận',N'Đã giao',N'Đã hủy')
UNION ALL
SELECT 'CANCELLATION_INVALID_STATUS', COUNT(*)
FROM dbo.ORDER_CANCELLATIONS
WHERE status NOT IN ('PENDING','APPROVED','REJECTED');

-- Active cart concurrency seed should not contain duplicate active carts.
SELECT user_email, COUNT(*) AS active_cart_count
FROM dbo.CARTS
WHERE status = 'ACTIVE'
GROUP BY user_email
HAVING COUNT(*) > 1;

-- Review database uniqueness must be product-level per canonical contract.
SELECT user_email, product_id, COUNT(*) AS duplicate_review_count
FROM dbo.REVIEWS
GROUP BY user_email, product_id
HAVING COUNT(*) > 1;

-- Pending cancellation must not already mutate the order to "Đã hủy".
SELECT c.id AS cancellation_id, c.order_id, c.status AS cancellation_status, o.status AS order_status
FROM dbo.ORDER_CANCELLATIONS c
JOIN dbo.ORDERS o ON o.id = c.order_id
WHERE c.status = 'PENDING'
  AND o.status = N'Đã hủy';
GO
